"""Name resolution and type checking for the AST subset.

Visibility rules
----------------
* A ``let`` binds from the statement *after* its declaration statement.
  (The initializer therefore cannot reference the variable itself.)
* Nested blocks push a fresh scope; an inner ``let`` shadows an outer
  binding of the same name (and is *not* a duplicate).
* A second ``let`` for the same name in the *same* scope raises
  :class:`DuplicateSymbolError`; a reference to an unbound name raises
  :class:`UndefinedSymbolError`.

Type rules
----------
* Arithmetic accepts only ``int`` operands and yields ``int``.
* Boolean ``and``/``or`` accept only ``bool`` and yield ``bool``.
* All six comparisons accept matching operand types and yield ``bool``;
  ``void`` never appears in an expression.
* Assignment, ``return`` and call arguments must match declarations.
* Calls must resolve to a known function with matching arity and argument
  types; the call type is the callee return type, so calls to ``void``
  functions are statement-less and rejectable.

This pass also computes reachability: a reachable path leaving a non-void
function without a ``return`` raises :class:`MissingReturnError`.
"""
from typing import Optional

from .errors import (
    DuplicateSymbolError,
    MissingReturnError,
    TypeCheckError,
    UndefinedSymbolError,
)

INT = "int"
BOOL = "bool"
VOID = "void"


class _Func:
    __slots__ = ("name", "param_types", "ret_type")

    def __init__(self, name: str, param_types: list[str], ret_type: str):
        self.name = name
        self.param_types = param_types
        self.ret_type = ret_type


class _Scope:
    """One block scope; ``declared`` is ordered for deterministic errors."""

    __slots__ = ("parent", "declared")

    def __init__(self, parent: Optional["_Scope"]):
        self.parent = parent
        self.declared: dict[str, str] = {}

    def declare(self, name: str, typ: str) -> None:
        if name in self.declared:
            raise DuplicateSymbolError(
                f"duplicate declaration of {name!r} in the same scope"
            )
        self.declared[name] = typ

    def lookup(self, name: str) -> Optional[str]:
        scope: Optional[_Scope] = self
        while scope is not None:
            if name in scope.declared:
                return scope.declared[name]
            scope = scope.parent
        return None


class SemanticAnalyzer:
    """Check one validated program AST."""

    def __init__(self, ast: dict):
        self.ast = ast
        # Function table is built in AST order for deterministic messages.
        self.functions: dict[str, _Func] = {}
        self._build_function_table()

    def _build_function_table(self) -> None:
        for func in self.ast["functions"]:
            name = func["name"]
            if name in self.functions:
                raise DuplicateSymbolError(
                    f"duplicate function declaration {name!r}"
                )
            self.functions[name] = _Func(
                name, [p["type"] for p in func["params"]], func["ret_type"]
            )

    def check(self) -> None:
        for func in self.ast["functions"]:
            self._check_function(func)

    # -- functions ---------------------------------------------------------

    def _check_function(self, func: dict) -> None:
        scope = _Scope(None)
        for param in func["params"]:
            # Parameter names occupy the top-level function scope; duplicates
            # here (e.g. two params of the same name) are also duplicates.
            scope.declare(param["name"], param["type"])
        self._ret_type = func["ret_type"]
        self._func_name = func["name"]
        completed = self._check_stmts(func["body"], scope)
        if self._ret_type != VOID and not completed:
            raise MissingReturnError(
                f"function {func['name']!r}: missing return on a reachable path"
            )

    # -- statements --------------------------------------------------------

    def _check_stmts(self, stmts: list, scope: _Scope) -> bool:
        """Return True if every path through these statements returns."""
        current = scope
        for stmt in stmts:
            if self._check_stmt(stmt, current):
                return True
        return False

    def _check_stmt(self, stmt: dict, scope: _Scope) -> bool:
        """Return True if control cannot reach the statement after this one."""
        kind = stmt["kind"]
        if kind == "let":
            typ = stmt["type"]
            # The initializer is checked *before* the name is bound: a let
            # is visible starting with the following statement.
            init_type = self._type_of(stmt["init"], scope)
            if init_type != typ:
                raise TypeCheckError(
                    f"let {stmt['name']!r}: declared {typ}, initializer is {init_type}"
                )
            scope.declare(stmt["name"], typ)
            return False
        if kind == "assign":
            name = stmt["target"]
            got = self._type_of(stmt["value"], scope)
            want = scope.lookup(name)
            if want is None:
                raise UndefinedSymbolError(
                    f"assignment to undeclared variable {name!r}"
                )
            if got != want:
                raise TypeCheckError(
                    f"assign to {name!r}: declared {want}, value is {got}"
                )
            return False
        if kind == "if":
            cond_t = self._type_of(stmt["cond"], scope)
            if cond_t != BOOL:
                raise TypeCheckError(f"if condition must be bool, got {cond_t}")
            then_done = self._check_stmts(stmt["then"], _Scope(scope))
            else_done = self._check_stmts(stmt["else"], _Scope(scope))
            return then_done and else_done
        if kind == "while":
            cond_t = self._type_of(stmt["cond"], scope)
            if cond_t != BOOL:
                raise TypeCheckError(f"while condition must be bool, got {cond_t}")
            # The loop may run zero times, so fallthrough always survives;
            # a return inside the body does not make the loop completing.
            self._check_stmts(stmt["body"], _Scope(scope))
            return False
        if kind == "return":
            value = stmt["value"]
            if self._ret_type == VOID:
                if value is not None:
                    got = self._type_of(value, scope)
                    raise TypeCheckError(
                        f"void function {self._func_name!r} returned {got}"
                    )
            else:
                if value is None:
                    raise TypeCheckError(
                        f"function {self._func_name!r} must return {self._ret_type}"
                    )
                got = self._type_of(value, scope)
                if got != self._ret_type:
                    raise TypeCheckError(
                        f"return in {self._func_name!r}: declared {self._ret_type}, got {got}"
                    )
            return True
        # block
        return self._check_stmts(stmt["body"], _Scope(scope))

    # -- expressions -------------------------------------------------------

    def _type_of(self, expr: dict, scope: _Scope) -> str:
        kind = expr["kind"]
        if kind == "int":
            return INT
        if kind == "bool":
            return BOOL
        if kind == "var":
            name = expr["name"]
            typ = scope.lookup(name)
            if typ is None:
                raise UndefinedSymbolError(f"reference to undeclared variable {name!r}")
            return typ
        if kind == "arith":
            lt = self._type_of(expr["left"], scope)
            rt = self._type_of(expr["right"], scope)
            if lt != INT or rt != INT:
                raise TypeCheckError(
                    f"arithmetic '{expr['op']}' requires int operands, got {lt} and {rt}"
                )
            return INT
        if kind == "compare":
            lt = self._type_of(expr["left"], scope)
            rt = self._type_of(expr["right"], scope)
            if lt != rt:
                raise TypeCheckError(
                    f"comparison '{expr['op']}' requires matching types, got {lt} and {rt}"
            )
            return BOOL
        if kind == "logical":
            lt = self._type_of(expr["left"], scope)
            rt = self._type_of(expr["right"], scope)
            if lt != BOOL or rt != BOOL:
                raise TypeCheckError(
                    f"boolean '{expr['op']}' requires bool operands, got {lt} and {rt}"
                )
            return BOOL
        # call
        name = expr["name"]
        func = self.functions.get(name)
        if func is None:
            raise UndefinedSymbolError(f"call to undeclared function {name!r}")
        args = expr["args"]
        if len(args) != len(func.param_types):
            raise TypeCheckError(
                f"call to {name!r}: expected {len(func.param_types)} "
                f"argument(s), got {len(args)}"
            )
        for i, (arg, want) in enumerate(zip(args, func.param_types)):
            got = self._type_of(arg, scope)
            if got != want:
                raise TypeCheckError(
                    f"call to {name!r} argument {i + 1}: expected {want}, got {got}"
                )
        if func.ret_type == VOID:
            raise TypeCheckError(
                f"call to void function {name!r} cannot be used as a value"
            )
        return func.ret_type


def analyze(ast: dict) -> None:
    """Run name resolution and type checking over a validated AST."""
    SemanticAnalyzer(ast).check()

"""The control-flow IR object model.

The IR is intentionally tiny and directly traversable::

    Module
      Function            (signature, local slots, basic blocks)
        Block             (phi nodes, ordered instructions, one terminator)
          Phi             (SSA only; one incoming value per predecessor)
          Instruction     (Const / Copy / BinOp / Call, all write a dest)
          Terminator      (Return / Jump / Branch)

Two flavors of module exist:

* non-SSA (produced by :func:`lower_module`): value references are
  :class:`Temp` -- numbered temporaries produced by instructions -- and
  :class:`Slot`, numbered mutable local storage (parameters and ``let``
  variables).  Temporaries are mostly single assignment; the sole exception
  is the result temporary of a short-circuit boolean operation, which is
  written once on each participating path, as is natural in non-SSA form.
* SSA (produced by :func:`to_ssa`): every parameter and every instruction
  result is a unique definition, slots never appear, and control-flow joins
  carry :class:`Phi` nodes listed before the block's ordinary instructions.

Both flavors reuse the same node classes; a module's ``ssa`` flag (and each
function's) says which one it is.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional, Union


@dataclass(frozen=True)
class Temp:
    id: int
    type: str

    def __str__(self) -> str:
        return f"%t{self.id}"


@dataclass(frozen=True)
class Slot:
    """A mutable local slot (parameter or ``let`` variable)."""

    id: int
    type: str

    def __str__(self) -> str:
        return f"%v{self.id}"


ValueRef = Union[Temp, Slot]


@dataclass
class Const:
    dest: Temp
    value: Union[int, bool]

    @property
    def op(self) -> str:
        return "const"


@dataclass
class Copy:
    dest: Union[Temp, Slot]
    src: ValueRef

    @property
    def op(self) -> str:
        return "copy"


@dataclass
class BinOp:
    dest: Temp
    operator: str
    left: ValueRef
    right: ValueRef
    kind: str  # "arith" or "compare"
    type: str  # result type

    @property
    def op(self) -> str:
        return self.kind


@dataclass
class Call:
    dest: Temp
    name: str
    args: list[ValueRef]
    type: str

    @property
    def op(self) -> str:
        return "call"


Instruction = Union[Const, Copy, BinOp, Call]


@dataclass(eq=False)
class Phi:
    """An SSA phi function: merges definitions from predecessor blocks.

    ``entries`` maps a predecessor :class:`Block` to the value that is live
    on that edge.  Entries are kept sorted by predecessor label whenever a
    module is emitted by :func:`to_ssa`; only reachable predecessors occur.
    """

    dest: Temp
    entries: dict["Block", ValueRef] = field(default_factory=dict)

    @property
    def op(self) -> str:
        return "phi"

    @property
    def type(self) -> str:
        return self.dest.type


@dataclass
class Return:
    value: Optional[ValueRef]

    @property
    def op(self) -> str:
        return "return"


@dataclass
class Jump:
    target: "Block"

    @property
    def op(self) -> str:
        return "jump"


@dataclass
class Branch:
    cond: ValueRef
    true_target: "Block"
    false_target: "Block"

    @property
    def op(self) -> str:
        return "br"


Terminator = Union[Return, Jump, Branch]


@dataclass(eq=False)
class Block:
    id: int
    instructions: list[Instruction] = field(default_factory=list)
    terminator: Optional[Terminator] = None
    # SSA only; empty in non-SSA blocks.  Phi nodes precede the ordinary
    # instructions.
    phis: list[Phi] = field(default_factory=list)

    @property
    def label(self) -> str:
        return f"b{self.id}"

    @property
    def is_terminated(self) -> bool:
        return self.terminator is not None


@dataclass
class Parameter:
    name: str
    slot: Slot
    # SSA only: the unique parameter definition.  None in non-SSA functions,
    # where the parameter is read through ``slot``.
    temp: Optional[Temp] = None


@dataclass
class Function:
    name: str
    params: list[Parameter]
    ret_type: str
    locals: list[Slot]
    blocks: list[Block]
    entry: Block
    ssa: bool = False

    def is_void(self) -> bool:
        return self.ret_type == "void"


@dataclass
class Module:
    functions: list[Function]
    ssa: bool = False

"""Standalone executor for instruction-selected SSA target text.

This is *test support* for the execution-level pass-order regression suite
in ``test_pass_order_execution.py``.  It is **not** part of the compiler
package and adds no production dependency: it is plain standard-library
Python, launched by the suite as a real operating-system process.

Why this exists
---------------
The language has no native code emitter; instruction selection is the
deterministic :func:`compiler_ir.render_module` plain-text emission, the
compiler's final stage.  The execution suite therefore:

1. compiles one legal source AST through the existing public entry points
   (``lower_module`` -> a legal permutation of ``to_ssa`` /
   ``fold_constants`` / ``eliminate_dead_code`` -> ``render_module``);
2. writes the rendered text to its own temporary target file;
3. *executes* that artifact in an isolated OS process and captures the
   real process exit status, standard output and standard error.

This module parses **only** rendered SSA text (every legal schedule in the
execution suite starts with ``to_ssa`` and ends in rendering) and executes
it directly.  It never imports the compiler: the target artifact is
self-contained, so no compiler object (symbol tables, temporary numbers,
analysis caches or pass state) can ride along into the executed program.

The observed output channel
---------------------------
The language has no I/O statement.  The only side effect a program can
perform is a function call, so calls to the reserved ``emit`` function
``emit(int) -> int`` are the standard-output surrogate: each executed call
writes its integer argument on its own line to stdout.  ``emit`` is the
identity, so its result is usable in surrounding arithmetic.

Process contract
----------------
* ``main`` returning a non-zero int or ``true`` -> exit status 1;
  returning zero or ``false`` -> 0; ``void main`` falling through -> 0.
* A runtime division/modulo by zero writes one line to stderr and exits 3.
* Any malformed target line, unknown instruction/terminator/operator,
  missing or duplicate SSA definition, bad block edge, type mismatch,
  non-bool branch, arity mismatch, non-integer argument or exhausted
  step/depth budget writes a diagnostic to stderr and exits 2.

Every target the compiler is expected to produce is well-formed and
terminating, so an exit 2/3 in the execution suite marks a broken order.
The exit status only carries 0/1 for ``main``; arbitrary integer results
are exchanged between functions inside the process (a concrete-value
recursive evaluator), while ``emit`` output still crosses the real
stdout boundary in execution order.
"""
from __future__ import annotations

import re
import sys


_STEP_LIMIT = 1_000_000
_DEPTH_LIMIT = 1_000


def _trunc_div(a, b):
    if b == 0:
        raise ZeroDivisionError
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return q


def _trunc_mod(a, b):
    if b == 0:
        raise ZeroDivisionError
    return a - _trunc_div(a, b) * b


_ARITH = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": lambda a, b: a * b,
    "div": _trunc_div,
    "mod": _trunc_mod,
}

_COMPARE = {
    "eq": lambda a, b: a == b,
    "ne": lambda a, b: a != b,
    "lt": lambda a, b: a < b,
    "le": lambda a, b: a <= b,
    "gt": lambda a, b: a > b,
    "ge": lambda a, b: a >= b,
}


def _fail(message):
    """Abort with status 2, distinct from every normal result."""
    sys.stderr.write("target-runner: malformed target: " + str(message)
                     + "\n")
    sys.stderr.flush()
    sys.exit(2)


def _trap(function_name, operator):
    sys.stderr.write(
        f"target-runner: runtime fault: {function_name}: {operator} by "
        "zero\n")
    sys.stderr.flush()
    sys.exit(3)


# ---------------------------------------------------------------------------
# Parsing
# ---------------------------------------------------------------------------

_FUNC_RE = re.compile(r"^function (\w+)\((.*)\) -> (int|bool|void) \{$")
_BLOCK_RE = re.compile(r"^  (b\d+):$")
_PARAM_RE = re.compile(r"^(\w+): (int|bool) @ %(\d+)$")
_CONST_RE = re.compile(r"^    %(\d+): (int|bool) = const (.+)$")
_BINOP_RE = re.compile(
    r"^    %(\d+): (int|bool) = (arith|compare) (\w+) %(\d+) %(\d+)$")
_CALL_RE = re.compile(
    r"^    %(\d+): (int|bool) = call (\w+)\((.*)\)$")
_PHI_RE = re.compile(
    r"^    (%\d+): (?:int|bool) = phi ((?:\[b\d+, %\d+\](?:, )?)+)$")
_PHI_ENTRY_RE = re.compile(r"\[(b\d+), (%\d+)\]")
_RETURN_RE = re.compile(r"^    return(?: (%\d+))?$")
_JUMP_RE = re.compile(r"^    jump (b\d+)$")
_BRANCH_RE = re.compile(r"^    br (%\d+), (b\d+), (b\d+)$")
_VALUE_RE = re.compile(r"^%(\d+)$")
_INT_RE = re.compile(r"^-?\d+$")


def _vid(token):
    m = _VALUE_RE.match(token)
    if not m:
        _fail(f"bad value reference {token!r}")
    return int(m.group(1))


def _literal(token):
    if token == "true":
        return True
    if token == "false":
        return False
    if _INT_RE.match(token):
        return int(token)
    _fail(f"bad literal {token!r}")


def _parse_params(text, lineno):
    if text == "":
        return []
    params = []
    for piece in text.split(", "):
        m = _PARAM_RE.match(piece)
        if not m:
            _fail(f"line {lineno}: bad parameter spec {piece!r}")
        name, typ, vid = m.groups()
        params.append((name, typ, int(vid)))
    return params


def _parse(text):
    """Parse rendered SSA text into {name: function dict}."""
    lines = text.splitlines()
    if not lines or lines[0].rstrip("\n") != "module":
        _fail("target text must start with 'module'")

    programs = {}
    fn = None
    block = None
    phi_zone = False

    for lineno, raw in enumerate(lines[1:], start=2):
        line = raw

        m = _FUNC_RE.match(line)
        if m:
            if fn is not None:
                _fail(f"line {lineno}: nested function")
            name, param_text, ret_type = m.groups()
            if name in programs:
                _fail(f"line {lineno}: duplicate function {name!r}")
            fn = {
                "name": name,
                "ret_type": ret_type,
                "params": _parse_params(param_text, lineno),
                "blocks": {},
                "order": [],
            }
            programs[name] = fn
            block = None
            continue

        if line == "}":
            if fn is None:
                _fail(f"line {lineno}: stray '}}'")
            if block is not None and block["terminator"] is None:
                _fail(f"line {lineno}: block {block['label']} has no "
                      "terminator")
            fn = None
            block = None
            continue

        if fn is None:
            if line.strip() == "":
                continue
            _fail(f"line {lineno}: unexpected line {line!r}")

        m = _BLOCK_RE.match(line)
        if m:
            label = m.group(1)
            if label in fn["blocks"]:
                _fail(f"line {lineno}: duplicate block {label}")
            if block is not None and block["terminator"] is None:
                _fail(f"line {lineno}: previous block has no terminator")
            block = {"label": label, "phis": [], "instructions": [],
                     "terminator": None}
            fn["blocks"][label] = block
            fn["order"].append(label)
            phi_zone = True
            continue

        if block is None:
            _fail(f"line {lineno}: instruction outside a block: {line!r}")

        m = _PHI_RE.match(line)
        if m:
            if not phi_zone:
                _fail(f"line {lineno}: phi after ordinary instructions")
            dest = _vid(m.group(1))
            entries = tuple(
                (em.group(1), _vid(em.group(2)))
                for em in _PHI_ENTRY_RE.finditer(m.group(2))
            )
            if not entries:
                _fail(f"line {lineno}: empty phi")
            preds = [e[0] for e in entries]
            if len(preds) != len(set(preds)):
                _fail(f"line {lineno}: phi lists a predecessor twice")
            block["phis"].append((dest, entries))
            continue
        phi_zone = False

        m = _CONST_RE.match(line)
        if m:
            dest, typ, token = m.groups()
            value = _literal(token)
            if typ == "int" and (not isinstance(value, int)
                                 or isinstance(value, bool)):
                _fail(f"line {lineno}: int const holds non-int literal")
            if typ == "bool" and not isinstance(value, bool):
                _fail(f"line {lineno}: bool const holds non-bool literal")
            block["instructions"].append(("const", int(dest), value))
            continue

        m = _BINOP_RE.match(line)
        if m:
            dest, _typ, kind, op, left, right = m.groups()
            table = _ARITH if kind == "arith" else _COMPARE
            if op not in table:
                _fail(f"line {lineno}: unknown {kind} operator {op!r}")
            block["instructions"].append(
                (kind, int(dest), op, int(left), int(right)))
            continue

        m = _CALL_RE.match(line)
        if m:
            dest, typ, callee, args_text = m.groups()
            arg_ids = (() if args_text == "" else
                       tuple(_vid(x.strip())
                             for x in args_text.split(",")))
            block["instructions"].append(
                ("call", int(dest), typ, callee, arg_ids))
            continue

        m = _RETURN_RE.match(line)
        if m:
            token = m.group(1)
            value_id = None if token is None else _vid(token)
            if (fn["ret_type"] == "void") != (value_id is None):
                _fail(f"line {lineno}: return shape disagrees with "
                      f"declared {fn['ret_type']} return")
            block["terminator"] = ("return", value_id)
            continue

        m = _JUMP_RE.match(line)
        if m:
            block["terminator"] = ("jump", m.group(1))
            continue

        m = _BRANCH_RE.match(line)
        if m:
            cond, t, f = m.groups()
            block["terminator"] = ("branch", _vid(cond), t, f)
            continue

        _fail(f"line {lineno}: unrecognized line {line!r}")

    if fn is not None:
        _fail("target text ends inside a function")
    if not programs:
        _fail("target text has no functions")
    if "main" not in programs:
        _fail("target text has no main function")

    for program in programs.values():
        _validate(program, programs)
    return programs


def _validate(fn, programs):
    """Cross-reference checks that line-local parsing cannot perform."""
    defined = {p[2] for p in fn["params"]}
    if len(defined) != len(fn["params"]):
        _fail(f"{fn['name']}: duplicate parameter SSA id")

    for label in fn["order"]:
        block = fn["blocks"][label]
        if block["terminator"] is None:
            _fail(f"{fn['name']}:{label}: missing terminator")
        for dest, entries in block["phis"]:
            if dest in defined:
                _fail(f"{fn['name']}:{label}: duplicate definition %{dest}")
            defined.add(dest)
            for pred, val_id in entries:
                if pred not in fn["blocks"]:
                    _fail(f"{fn['name']}:{label}: phi from unknown "
                          f"predecessor {pred}")
        for ins in block["instructions"]:
            dest = ins[1]
            if dest in defined:
                _fail(f"{fn['name']}:{label}: duplicate definition %{dest}")
            defined.add(dest)

    def require(value_id, where):
        if value_id not in defined:
            _fail(f"{fn['name']}:{where}: reference to undefined "
                  f"%{value_id}")

    for label in fn["order"]:
        block = fn["blocks"][label]
        for dest, entries in block["phis"]:
            for pred, val_id in entries:
                require(val_id, label)
        for ins in block["instructions"]:
            if ins[0] == "const":
                pass
            elif ins[0] in ("arith", "compare"):
                require(ins[3], label)
                require(ins[4], label)
            elif ins[0] == "call":
                _typ, callee, arg_ids = ins[2], ins[3], ins[4]
                for arg in arg_ids:
                    require(arg, label)
                if callee == "emit":
                    if _typ != "int" or len(arg_ids) != 1:
                        _fail(f"{fn['name']}:{label}: emit must be "
                              "emit(int) -> int")
                elif callee not in programs:
                    _fail(f"{fn['name']}:{label}: call to unknown "
                          f"function {callee!r}")
                else:
                    callee_params = programs[callee]["params"]
                    if len(arg_ids) != len(callee_params):
                        _fail(f"{fn['name']}:{label}: arity mismatch in "
                              f"call to {callee!r}")
        term = block["terminator"]
        if term[0] == "return":
            if term[1] is not None:
                require(term[1], label)
        elif term[0] == "jump":
            if term[1] not in fn["blocks"]:
                _fail(f"{fn['name']}:{label}: jump to unknown "
                      f"{term[1]}")
        elif term[0] == "branch":
            require(term[1], label)
            for target in (term[2], term[3]):
                if target not in fn["blocks"]:
                    _fail(f"{fn['name']}:{label}: branch to unknown "
                          f"{target}")


# ---------------------------------------------------------------------------
# Execution
# ---------------------------------------------------------------------------


class _Engine:
    def __init__(self, programs):
        self.programs = programs

    def invoke_main(self, arguments):
        """Run main with concrete argument values; return its exit status."""
        value = self._invoke("main", arguments, depth=0, steps=[_STEP_LIMIT])
        main_type = self.programs["main"]["ret_type"]
        if main_type == "void":
            return 0
        if main_type == "int":
            if not isinstance(value, int) or isinstance(value, bool):
                _fail("main: int function produced non-int")
            return 1 if value != 0 else 0
        if isinstance(value, bool):
            return 1 if value else 0
        _fail("main: bool function produced non-bool")

    def _invoke(self, name, arguments, depth, steps):
        if depth > _DEPTH_LIMIT:
            _fail(f"{name}: call depth limit exceeded")
        fn = self.programs[name]
        if len(arguments) != len(fn["params"]):
            _fail(f"{name}: arity mismatch ({len(arguments)} for "
                  f"{len(fn['params'])})")

        values = {
            param[2]: arg for param, arg in zip(fn["params"], arguments)
        }
        label = fn["order"][0]
        previous = None

        while True:
            steps[0] -= 1
            if steps[0] <= 0:
                _fail(f"{name}: step budget exhausted (non-terminating?)")

            block = fn["blocks"][label]

            # All incoming values are read off the actual predecessor edge
            # before any phi result is bound.
            pending = []
            for dest, entries in block["phis"]:
                if previous is None:
                    _fail(f"{name}:{label}: phi reached on entry")
                incoming = dict(entries)
                if previous not in incoming:
                    _fail(f"{name}:{label}: phi has no incoming value "
                          f"from {previous}")
                pending.append((dest, values[incoming[previous]]))
            values.update(pending)

            for ins in block["instructions"]:
                self._execute(fn, values, ins, depth, steps)

            term = block["terminator"]
            if term[0] == "return":
                if term[1] is None:
                    return None
                return values[term[1]]

            if term[0] == "jump":
                previous, label = label, term[1]
                continue

            cond = values[term[1]]
            if not isinstance(cond, bool):
                _fail(f"{name}:{label}: branch on non-bool {cond!r}")
            previous, label = label, (term[2] if cond else term[3])

    def _execute(self, fn, values, ins, depth, steps):
        tag = ins[0]
        if tag == "const":
            values[ins[1]] = ins[2]
            return

        if tag in ("arith", "compare"):
            _kind, dest, op, left_id, right_id = ins
            left = values[left_id]
            right = values[right_id]
            if tag == "arith":
                if not isinstance(left, int) or isinstance(left, bool) or \
                        not isinstance(right, int) or isinstance(right, bool):
                    _fail(f"{fn['name']}: arithmetic on non-int operands")
                try:
                    result = _ARITH[op](left, right)
                except ZeroDivisionError:
                    _trap(fn["name"], op)
            else:
                if type(left) is not type(right):
                    _fail(f"{fn['name']}: comparison between mismatched "
                          "types")
                result = _COMPARE[op](left, right)
            values[dest] = result
            return

        if tag == "call":
            _kind, dest, _typ, callee, arg_ids = ins
            args = [values[arg] for arg in arg_ids]
            if callee == "emit":
                arg = args[0]
                if not isinstance(arg, int) or isinstance(arg, bool):
                    _fail(f"{fn['name']}: emit of non-int value")
                sys.stdout.write(str(arg) + "\n")
                sys.stdout.flush()
                values[dest] = arg
                return
            callee_fn = self.programs[callee]
            for param, arg in zip(callee_fn["params"], args):
                ptype = param[1]
                if ptype == "int" and (not isinstance(arg, int)
                                       or isinstance(arg, bool)):
                    _fail(f"{fn['name']}->{callee}: int argument got "
                          f"{arg!r}")
                if ptype == "bool" and not isinstance(arg, bool):
                    _fail(f"{fn['name']}->{callee}: bool argument got "
                          f"{arg!r}")
            values[dest] = self._invoke(callee, args, depth + 1, steps)
            return

        _fail(f"{fn['name']}: unknown instruction {ins!r}")


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------


def _read_arguments(path):
    with open(path, "r", encoding="utf-8") as fh:
        tokens = [line.rstrip("\n") for line in fh if line != "\n"]
    return [_literal(token) for token in tokens]


def main(argv):
    if len(argv) != 3:
        sys.stderr.write(
            "usage: target_runner.py <target-file> <arguments-file>\n")
        return 2
    try:
        with open(argv[1], "r", encoding="utf-8") as fh:
            text = fh.read()
        arguments = _read_arguments(argv[2])
    except OSError as exc:
        _fail(f"cannot read inputs: {exc}")

    programs = _parse(text)
    main_fn = programs["main"]
    if len(arguments) != len(main_fn["params"]):
        _fail(f"main expects {len(main_fn['params'])} argument(s), got "
              f"{len(arguments)}")
    for param, arg in zip(main_fn["params"], arguments):
        pname, ptype, _vid_ = param
        if ptype == "int" and (not isinstance(arg, int)
                               or isinstance(arg, bool)):
            _fail(f"argument {pname!r}: expected int, got {arg!r}")
        if ptype == "bool" and not isinstance(arg, bool):
            _fail(f"argument {pname!r}: expected bool, got {arg!r}")

    return _Engine(programs).invoke_main(arguments)


if __name__ == "__main__":
    sys.exit(main(sys.argv))

"""Exception hierarchy for the compiler-ir pipeline."""


class CompilerError(Exception):
    """Base class for all compiler errors."""


class InvalidAstError(CompilerError):
    """The program AST is structurally malformed.

    ``path`` is a human-readable, locatable path into the AST (for example
    ``module.functions[2].body[1].cond``); it is also appended to the
    exception message.
    """

    def __init__(self, message: str, path: str = "module"):
        self.path = path
        super().__init__(f"{message} (at {path})")


class DuplicateSymbolError(CompilerError):
    """A name is declared twice in the same scope."""


class UndefinedSymbolError(CompilerError):
    """A name is used before (or without) being declared."""


class TypeCheckError(CompilerError):
    """The program is well formed but not well typed."""


class MissingReturnError(CompilerError):
    """A non-``void`` function has a reachable path without a ``return``."""

"""Structural validation of the dict/list program AST.

The AST is plain data produced by callers; this pass only checks shape
(required fields, node kinds, type names, list lengths, literal types) and
never performs name resolution or type checking.  Every failure raises
:class:`InvalidAstError` carrying a locatable path into the AST.
"""
from typing import Any

from .errors import InvalidAstError

INT = "int"
BOOL = "bool"
VOID = "void"
VALUE_TYPES = (INT, BOOL)
ALL_TYPES = (INT, BOOL, VOID)

ARITH_OPS = ("add", "sub", "mul", "div", "mod")
COMPARE_OPS = ("eq", "ne", "lt", "le", "gt", "ge")
LOGICAL_OPS = ("and", "or")

STATEMENT_KINDS = ("let", "assign", "if", "while", "return", "block")
EXPRESSION_KINDS = (
    "int", "bool", "var", "arith", "compare", "logical", "call",
)


def _fail(path: str, message: str) -> None:
    raise InvalidAstError(message, path)


def _is_ident(value: Any) -> bool:
    return (
        isinstance(value, str)
        and len(value) > 0
        and (value[0].isalpha() or value[0] == "_")
        and all(c.isalnum() or c == "_" for c in value)
    )


def _check_value_type(value: Any, path: str) -> None:
    if not isinstance(value, str) or value not in VALUE_TYPES:
        _fail(path, f"illegal type name {value!r}: expected 'int' or 'bool'")


def validate_program(ast: Any) -> dict:
    """Validate a whole program AST and return it unchanged."""
    path = "module"
    if not isinstance(ast, dict):
        _fail(path, f"program AST must be a dict, got {type(ast).__name__}")
    if "functions" not in ast:
        _fail(path, "missing required field 'functions'")
    funcs = ast["functions"]
    if not isinstance(funcs, list):
        _fail(f"{path}.functions", "must be a list")
    for i, func in enumerate(funcs):
        _validate_function(func, f"{path}.functions[{i}]")
    return ast


def _validate_function(func: Any, path: str) -> None:
    if not isinstance(func, dict):
        _fail(path, f"function must be a dict, got {type(func).__name__}")
    for field in ("name", "params", "ret_type", "body"):
        if field not in func:
            _fail(path, f"missing required field '{field}'")
    name = func["name"]
    if not _is_ident(name):
        _fail(f"{path}.name", f"invalid function name {name!r}")
    params = func["params"]
    if not isinstance(params, list):
        _fail(f"{path}.params", "must be a list")
    for i, param in enumerate(params):
        _validate_param(param, f"{path}.params[{i}]")
    ret = func["ret_type"]
    if not isinstance(ret, str) or ret not in ALL_TYPES:
        _fail(
            f"{path}.ret_type",
            f"illegal type name {ret!r}: expected 'int', 'bool' or 'void'",
        )
    _validate_block_body(func["body"], f"{path}.body")
    extra = set(func) - {"name", "params", "ret_type", "body"}
    if extra:
        _fail(path, f"unknown function field(s): {', '.join(sorted(extra))}")


def _validate_param(param: Any, path: str) -> None:
    if not isinstance(param, dict):
        _fail(path, f"parameter must be a dict, got {type(param).__name__}")
    for field in ("name", "type"):
        if field not in param:
            _fail(path, f"missing required field '{field}'")
    if not _is_ident(param["name"]):
        _fail(f"{path}.name", f"invalid parameter name {param['name']!r}")
    _check_value_type(param["type"], f"{path}.type")
    extra = set(param) - {"name", "type"}
    if extra:
        _fail(path, f"unknown parameter field(s): {', '.join(sorted(extra))}")


def _validate_block_body(body: Any, path: str) -> None:
    if not isinstance(body, list):
        _fail(path, f"statement list must be a list, got {type(body).__name__}")
    for i, stmt in enumerate(body):
        validate_statement(stmt, f"{path}[{i}]")


def validate_statement(stmt: Any, path: str) -> None:
    if not isinstance(stmt, dict):
        _fail(path, f"statement must be a dict, got {type(stmt).__name__}")
    if "kind" not in stmt:
        _fail(path, "missing required field 'kind'")
    kind = stmt["kind"]
    if kind not in STATEMENT_KINDS:
        _fail(path, f"unknown statement kind {kind!r}")
    if kind == "let":
        for field in ("name", "type", "init"):
            if field not in stmt:
                _fail(path, f"missing required field '{field}'")
        if not _is_ident(stmt["name"]):
            _fail(f"{path}.name", f"invalid variable name {stmt['name']!r}")
        _check_value_type(stmt["type"], f"{path}.type")
        _validate_expr(stmt["init"], f"{path}.init")
        extra = set(stmt) - {"kind", "name", "type", "init"}
    elif kind == "assign":
        for field in ("target", "value"):
            if field not in stmt:
                _fail(path, f"missing required field '{field}'")
        if not _is_ident(stmt["target"]):
            _fail(f"{path}.target", f"invalid variable name {stmt['target']!r}")
        _validate_expr(stmt["value"], f"{path}.value")
        extra = set(stmt) - {"kind", "target", "value"}
    elif kind == "if":
        for field in ("cond", "then", "else"):
            if field not in stmt:
                _fail(path, f"missing required field '{field}'")
        _validate_expr(stmt["cond"], f"{path}.cond")
        _validate_block_body(stmt["then"], f"{path}.then")
        _validate_block_body(stmt["else"], f"{path}.else")
        extra = set(stmt) - {"kind", "cond", "then", "else"}
    elif kind == "while":
        for field in ("cond", "body"):
            if field not in stmt:
                _fail(path, f"missing required field '{field}'")
        _validate_expr(stmt["cond"], f"{path}.cond")
        _validate_block_body(stmt["body"], f"{path}.body")
        extra = set(stmt) - {"kind", "cond", "body"}
    elif kind == "return":
        if "value" not in stmt:
            _fail(path, "missing required field 'value'")
        if stmt["value"] is not None:
            _validate_expr(stmt["value"], f"{path}.value")
        extra = set(stmt) - {"kind", "value"}
    else:  # block
        if "body" not in stmt:
            _fail(path, "missing required field 'body'")
        _validate_block_body(stmt["body"], f"{path}.body")
        extra = set(stmt) - {"kind", "body"}
    if extra:
        _fail(path, f"unknown {kind} statement field(s): {', '.join(sorted(extra))}")


def _validate_expr(expr: Any, path: str) -> None:
    if not isinstance(expr, dict):
        _fail(path, f"expression must be a dict, got {type(expr).__name__}")
    if "kind" not in expr:
        _fail(path, "missing required field 'kind'")
    kind = expr["kind"]
    if kind not in EXPRESSION_KINDS:
        _fail(path, f"unknown expression kind {kind!r}")
    if kind == "int":
        if "value" not in expr:
            _fail(path, "missing required field 'value'")
        # bool is a subclass of int: reject it explicitly.
        if not isinstance(expr["value"], int) or isinstance(expr["value"], bool):
            _fail(
                f"{path}.value",
                f"int literal must be an integer, got {type(expr['value']).__name__}",
            )
        extra = set(expr) - {"kind", "value"}
    elif kind == "bool":
        if "value" not in expr:
            _fail(path, "missing required field 'value'")
        if not isinstance(expr["value"], bool):
            _fail(
                f"{path}.value",
                f"bool literal must be true/false, got {type(expr['value']).__name__}",
            )
        extra = set(expr) - {"kind", "value"}
    elif kind == "var":
        if "name" not in expr:
            _fail(path, "missing required field 'name'")
        if not _is_ident(expr["name"]):
            _fail(f"{path}.name", f"invalid variable name {expr['name']!r}")
        extra = set(expr) - {"kind", "name"}
    elif kind in ("arith", "compare", "logical"):
        for field in ("op", "left", "right"):
            if field not in expr:
                _fail(path, f"missing required field '{field}'")
        op = expr["op"]
        if kind == "arith":
            allowed = ARITH_OPS
        elif kind == "compare":
            allowed = COMPARE_OPS
        else:
            allowed = LOGICAL_OPS
        if not isinstance(op, str) or op not in allowed:
            _fail(
                f"{path}.op",
                f"unknown {kind} operator {op!r}: expected one of {', '.join(allowed)}",
            )
        _validate_expr(expr["left"], f"{path}.left")
        _validate_expr(expr["right"], f"{path}.right")
        extra = set(expr) - {"kind", "op", "left", "right"}
    else:  # call
        for field in ("name", "args"):
            if field not in expr:
                _fail(path, f"missing required field '{field}'")
        if not _is_ident(expr["name"]):
            _fail(f"{path}.name", f"invalid callee name {expr['name']!r}")
        args = expr["args"]
        if not isinstance(args, list):
            _fail(f"{path}.args", "must be a list")
        for i, arg in enumerate(args):
            _validate_expr(arg, f"{path}.args[{i}]")
        extra = set(expr) - {"kind", "name", "args"}
    if extra:
        _fail(path, f"unknown {kind} expression field(s): {', '.join(sorted(extra))}")

"""Tests for AST validation, semantic analysis, lowering and text IR."""
import unittest

from compiler_ir import (
    DuplicateSymbolError,
    InvalidAstError,
    MissingReturnError,
    TypeCheckError,
    UndefinedSymbolError,
    emit_ir,
    lower_module,
    render_module,
)


def int_(value):
    return {"kind": "int", "value": value}


def bool_(value):
    return {"kind": "bool", "value": value}


def var(name):
    return {"kind": "var", "name": name}


def arith(op, left, right):
    return {"kind": "arith", "op": op, "left": left, "right": right}


def compare(op, left, right):
    return {"kind": "compare", "op": op, "left": left, "right": right}


def logical(op, left, right):
    return {"kind": "logical", "op": op, "left": left, "right": right}


def call(name, args):
    return {"kind": "call", "name": name, "args": args}


def let(name, typ, init):
    return {"kind": "let", "name": name, "type": typ, "init": init}


def assign(target, value):
    return {"kind": "assign", "target": target, "value": value}


def if_(cond, then, else_=None):
    return {"kind": "if", "cond": cond, "then": then, "else": else_ or []}


def while_(cond, body):
    return {"kind": "while", "cond": cond, "body": body}


def ret(value=None):
    return {"kind": "return", "value": value}


def block(body):
    return {"kind": "block", "body": body}


def func(name, params, ret_type, body):
    return {"name": name, "params": params, "ret_type": ret_type, "body": body}


def param(name, typ):
    return {"name": name, "type": typ}


def program(*funcs):
    return {"functions": list(funcs)}


# Two mutually recursive-ish int functions used across tests.
COUNTER = func(
    "counter",
    [param("n", "int")],
    "int",
    [
        let("acc", "int", int_(0)),
        while_(
            compare("gt", var("n"), int_(0)),
            [
                assign("acc", arith("add", var("acc"), var("n"))),
                assign("n", arith("sub", var("n"), int_(1))),
            ],
        ),
        ret(var("acc")),
    ],
)


class LoweringTests(unittest.TestCase):
    def test_empty_void_function(self):
        text = emit_ir(program(func("noop", [], "void", [])))
        self.assertIn("function noop() -> void", text)
        self.assertIn("b0:", text)
        # The entry block's terminator is an explicit bare return.
        body = text[text.index("b0:"):]
        self.assertIn("    return\n", body)

    def test_nonvoid_with_constant_return(self):
        text = emit_ir(program(func("answer", [], "int", [ret(int_(42))])))
        self.assertIn("const 42", text)
        self.assertIn("return %t0", text)

    def test_parameters_occupy_first_slots(self):
        module = lower_module(
            program(func("add", [param("a", "int"), param("b", "int")], "int",
                        [ret(arith("add", var("a"), var("b")))]))
        )
        fn = module.functions[0]
        self.assertEqual([p.slot.id for p in fn.params], [0, 1])
        self.assertEqual(fn.locals, [])

"""SSA constant folding and propagation.

The entry point :func:`fold_constants` takes an SSA :class:`Module`
produced by :func:`~compiler_ir.ssa.to_ssa` and returns a brand new SSA
:class:`Module` in which known literal values are propagated along the SSA
def-use chains; the input module is never mutated and shares no mutable
function, block, instruction or phi container with the result.

A value is *known* when it is statically provably a fixed literal:

* a ``Const`` definition is known directly;
* an arithmetic or compare ``BinOp`` folds only when both operands are
  known, and its result becomes known for subsequent definitions;
* a ``Phi`` folds exactly when the literals arriving on *every* reachable
  predecessor edge are all known and identical (a phi's own result is not
  an incoming definition and cannot occur there).

Arithmetic covers ``add``, ``sub``, ``mul``, ``div`` and ``mod``, and
comparisons ``eq``, ``ne``, ``lt``, ``le``, ``gt`` and ``ge``; the int and
bool result types are preserved.  Integer division truncates toward zero
and the remainder satisfies ``a == div(a,b) * b + mod(a,b)``.  A known
zero divisor must not be folded away: the original ``BinOp`` is kept so the
runtime trap and its position in the instruction stream are neither
advanced, swallowed nor rewritten.  A ``Call`` result is always unknown,
and the call instruction together with its relative order is untouched.

Because a loop header phi can look constant on its (constant) entry edge
before the back edge is analyzed, literals are tracked in a monotone
three-level lattice -- unknown, constant ``k``, and non-constant -- solved
to a fixpoint: a phi starts unknown, sinks to its first seen literal and
reaches non-constant as soon as two edges disagree (or an edge carries a
non-constant value).  This is the lattice half of sparse conditional
constant propagation; the reachability half is deliberately absent, so no
blocks are deleted, no constant ``Branch`` becomes a ``Jump``, and
definitions made pointless by folding are left in place for
:func:`~compiler_ir.dce.eliminate_dead_code` to remove.

Folded definitions become a ``Const`` in their *own* SSA slot (the same
value number), so no operand needs rewriting: every existing use already
names that slot, which now holds the literal.  A folded phi loses its phi
node and contributes its ``Const`` ahead of the block's ordinary
instructions (in phi order), matching where the merge value is defined.

Function order, signatures, parameters, block labels and order,
terminators, phi order, the relative order of all instructions and the
existing SSA numbers are all preserved; the output therefore has the same
definition slots as the input.  Applying the pass again gives a
structurally and textually identical fixed point.

A non-:class:`Module` object raises :class:`TypeError`; a non-SSA
:class:`Module` raises :class:`ValueError`.
"""
from .ir_nodes import (
    BinOp,
    Block,
    Branch,
    Call,
    Const,
    Copy,
    Function,
    Jump,
    Module,
    Parameter,
    Phi,
    Return,
    Temp,
)


# Per-value lattice levels (keyed by SSA value id):
#   absent/None      -> unknown (not yet constrained; a phi's initial state)
#   int/bool literal -> known to be exactly that literal
#   _BOTTOM          -> not a compile-time constant
_BOTTOM = object()


def _same_literal(a, b) -> bool:
    # Type-strict equality: the SSA type system never lets an int and a
    # bool meet, but Python's ``True == 1`` must not merge them if a
    # malformed module ever does.
    return type(a) is type(b) and a == b


def fold_constants(module: Module) -> Module:
    """Return a new SSA :class:`Module` with literals folded and propagated.

    The input module is left untouched; the result shares no mutable
    function, block, instruction or phi object with it.  The empty module
    and modules without foldable definitions come back as independent,
    content-equivalent copies.

    :raises TypeError: if ``module`` is not a :class:`Module` instance.
    :raises ValueError: if ``module`` is not in SSA form.
    """
    if not isinstance(module, Module):
        raise TypeError(
            "fold_constants expects a Module, got "
            f"{type(module).__name__}"
        )
    if not getattr(module, "ssa", False):
        raise ValueError("fold_constants expects an SSA Module")
    return Module(
        [_Folder(func).build() for func in module.functions], ssa=True
    )


# --------------------------------------------------------------------------
# Arithmetic / comparison semantics (truncated toward zero, like the runtime)
# --------------------------------------------------------------------------


def _trunc_div(a: int, b: int) -> int:
    """Integer division truncated toward zero.

    Only called for a provably non-zero divisor; a zero divisor is handled
    by the caller so the faulting instruction stays in the stream.
    """
    quotient = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        quotient = -quotient
    return quotient


def _trunc_mod(a: int, b: int) -> int:
    # a == div(a,b) * b + mod(a,b)
    return a - _trunc_div(a, b) * b


_ARITH = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": lambda a, b: a * b,
    "div": _trunc_div,
    "mod": _trunc_mod,
}

_COMPARE = {
    "eq": lambda a, b: a == b,
    "ne": lambda a, b: a != b,
    "lt": lambda a, b: a < b,
    "le": lambda a, b: a <= b,
    "gt": lambda a, b: a > b,
    "ge": lambda a, b: a >= b,
}


# --------------------------------------------------------------------------
# Per-function fixpoint and output construction
# --------------------------------------------------------------------------


class _Folder:
    def __init__(self, func: Function):
        self.func = func
        self.lattice: dict = {}
        # Definition id -> user nodes that re-read it, tagged by kind.
        self.users: dict = {}
        self.worklist: list = []

    # -- lattice ------------------------------------------------------------

    def get(self, value):
        return self.lattice.get(id(value))

    def constrain(self, value, level) -> bool:
        """Monotonically move ``value`` toward ``level``.

        Returns whether its level changed.  ``None`` (unknown) never
        constrains anything; two disagreeing literals collapse to
        ``_BOTTOM``.
        """
        if level is None:
            return False
        current = self.lattice.get(id(value))
        if current is _BOTTOM:
            return False
        if current is None:
            self.lattice[id(value)] = level
            return True
        if level is not _BOTTOM and _same_literal(current, level):
            return False
        self.lattice[id(value)] = _BOTTOM
        return True

    def note_user(self, operand, user) -> None:
        self.users.setdefault(id(operand), []).append(user)

    def enqueue_users(self, value) -> None:
        self.worklist.extend(self.users.get(id(value), ()))

    # -- transfer functions -------------------------------------------------

    def phi_level(self, phi: Phi):
        """Join over every reachable incoming edge."""
        result = None
        for value in phi.entries.values():
            level = self.get(value)
            if level is _BOTTOM:
                return _BOTTOM
            if level is None:
                continue
            if result is None:
                result = level
            elif not _same_literal(result, level):
                return _BOTTOM
        return result

    def binop_level(self, ins: BinOp):
        left = self.get(ins.left)
        right = self.get(ins.right)
        if left is None or right is None:
            return None
        if left is _BOTTOM or right is _BOTTOM:
            return _BOTTOM
        if ins.kind == "arith":
            if ins.operator in ("div", "mod") and right == 0:
                # The operands are known but the operation traps: keep the
                # BinOp (its result is never observed), so mark the result
                # non-constant rather than folding the fault away.
                return _BOTTOM
            return _ARITH[ins.operator](left, right)
        return _COMPARE[ins.operator](left, right)

    # -- fixpoint ------------------------------------------------------------

    def solve(self) -> None:
        # Parameters are never statically known.
        for param in self.func.params:
            self.constrain(param.temp, _BOTTOM)

        # Register users and seed every definition.  Traversal order is the
        # deterministic numbering order (blocks in id order, phis before
        # instructions); it affects only iteration count, not the fixpoint.
        for block in self.func.blocks:
            for phi in block.phis:
                for value in phi.entries.values():
                    self.note_user(value, ("phi", phi))
                self.worklist.append(("phi", phi))
            for ins in block.instructions:
                if isinstance(ins, Const):
                    self.worklist.append(("const", ins))
                elif isinstance(ins, BinOp):
                    self.note_user(ins.left, ("binop", ins))
                    self.note_user(ins.right, ("binop", ins))
                    self.worklist.append(("binop", ins))
                elif isinstance(ins, Call):
                    # Call results are always unknown.
                    self.constrain(ins.dest, _BOTTOM)
                elif isinstance(ins, Copy):
                    self.note_user(ins.src, ("copy", ins))
                    self.worklist.append(("copy", ins))

        while self.worklist:
            kind, node = self.worklist.pop()
            if kind == "const":
                changed = self.constrain(node.dest, node.value)
            elif kind == "binop":
                changed = self.constrain(node.dest, self.binop_level(node))
            elif kind == "copy":
                changed = self.constrain(node.dest, self.get(node.src))
            else:
                changed = self.constrain(node.dest, self.phi_level(node))
            if changed:
                self.enqueue_users(node.dest)

    def is_constant(self, value):
        """The settled literal for ``value``, or None if not a constant."""
        level = self.lattice.get(id(value))
        if level is None or level is _BOTTOM:
            return None
        return level

    # -- output --------------------------------------------------------------

    def build(self) -> Function:
        self.solve()

        new_blocks = [Block(block.id) for block in self.func.blocks]
        block_map = dict(zip(self.func.blocks, new_blocks))

        # One fresh Temp per original definition, preserving original ids;
        # every existing operand keeps pointing at the same slot.
        value_map: dict = {}

        def fresh(value: Temp) -> Temp:
            mapped = value_map.get(id(value))
            if mapped is None:
                mapped = Temp(value.id, value.type)
                value_map[id(value)] = mapped
            return mapped

        for param in self.func.params:
            fresh(param.temp)
        for block in self.func.blocks:
            for phi in block.phis:
                fresh(phi.dest)
            for ins in block.instructions:
                fresh(ins.dest)

        def map_value(value):
            if value is None:
                return None
            return value_map[id(value)]

        for block, new_block in zip(self.func.blocks, new_blocks):
            # Folded phis become leading Consts (in phi order); surviving
            # phis keep their entries and predecessor order.
            for phi in block.phis:
                literal = self.is_constant(phi.dest)
                if literal is not None:
                    new_block.instructions.append(
                        Const(map_value(phi.dest), literal)
                    )
                else:
                    entries = {
                        block_map[pred]: map_value(value)
                        for pred, value in sorted(
                            phi.entries.items(), key=lambda item: item[0].id
                        )
                    }
                    new_block.phis.append(
                        Phi(map_value(phi.dest), entries)
                    )

            for ins in block.instructions:
                new_block.instructions.append(
                    self._clone_instruction(ins, map_value)
                )

            term = block.terminator
            if isinstance(term, Return):
                new_block.terminator = Return(map_value(term.value))
            elif isinstance(term, Jump):
                new_block.terminator = Jump(block_map[term.target])
            elif isinstance(term, Branch):
                new_block.terminator = Branch(
                    map_value(term.cond),
                    block_map[term.true_target],
                    block_map[term.false_target],
                )

        new_params = [
            Parameter(param.name, param.slot, map_value(param.temp))
            for param in self.func.params
        ]

        return Function(
            self.func.name,
            new_params,
            self.func.ret_type,
            list(self.func.locals),
            new_blocks,
            block_map[self.func.entry],
            ssa=True,
        )

    def _clone_instruction(self, ins, map_value):
        if isinstance(ins, Const):
            return Const(map_value(ins.dest), ins.value)
        if isinstance(ins, BinOp):
            literal = self.is_constant(ins.dest)
            if literal is not None:
                return Const(map_value(ins.dest), literal)
            return BinOp(
                map_value(ins.dest), ins.operator,
                map_value(ins.left), map_value(ins.right),
                ins.kind, ins.type,
            )
        if isinstance(ins, Call):
            return Call(
                map_value(ins.dest), ins.name,
                [map_value(arg) for arg in ins.args], ins.type,
            )
        # Copy cannot survive to_ssa; handled defensively as pure aliasing.
        if isinstance(ins, Copy):
            return Copy(map_value(ins.dest), map_value(ins.src))
        raise AssertionError(f"unknown instruction: {ins!r}")  # pragma: no cover

"""Deterministic plain-text rendering of the IR.

The output is a direct, fixed-order walk of the IR tree: functions in
module order, blocks in id order, phi nodes (SSA only) then instructions in
emission order.  Nothing is sorted by name or derived from object identity
-- phi entries are ordered by predecessor label, which is itself fixed -- so
a given module renders byte-identically across processes and repeated
conversions.

Non-SSA modules render exactly as before (``%tN`` temporaries, ``%vN``
slots).  SSA modules use a distinct representation: every value is a unique
``%N`` definition, parameters are rendered with their SSA value, no locals
section is emitted, and phi lines carry the result type plus one
``[block, value]`` pair per reachable predecessor.
"""
from .ir_nodes import (
    BinOp,
    Branch,
    Call,
    Const,
    Copy,
    Function,
    Jump,
    Module,
    Phi,
    Return,
)


def _render_instruction(ins, value) -> str:
    if isinstance(ins, Const):
        literal = "true" if ins.value is True else "false" if ins.value is False else str(ins.value)
        return f"    {value(ins.dest)}: {ins.dest.type} = const {literal}"
    if isinstance(ins, Copy):
        return f"    {value(ins.dest)}: {ins.dest.type} = copy {value(ins.src)}"
    if isinstance(ins, BinOp):
        return (
            f"    {value(ins.dest)}: {ins.type} = {ins.kind} {ins.operator} "
            f"{value(ins.left)} {value(ins.right)}"
        )
    if isinstance(ins, Call):
        args = ", ".join(value(a) for a in ins.args)
        return f"    {value(ins.dest)}: {ins.type} = call {ins.name}({args})"
    raise AssertionError(f"unknown instruction: {ins!r}")  # pragma: no cover


def _render_phi(phi: Phi, value) -> str:
    sources = ", ".join(
        f"[{block.label}, {value(val)}]"
        for block, val in sorted(phi.entries.items(), key=lambda item: item[0].id)
    )
    return f"    {value(phi.dest)}: {phi.type} = phi {sources}"


def _render_terminator(term, value) -> str:
    if isinstance(term, Return):
        if term.value is None:
            return "    return"
        return f"    return {value(term.value)}"
    if isinstance(term, Jump):
        return f"    jump {term.target.label}"
    if isinstance(term, Branch):
        return (
            f"    br {value(term.cond)}, {term.true_target.label}, "
            f"{term.false_target.label}"
        )
    raise AssertionError(f"unknown terminator: {term!r}")  # pragma: no cover


def _render_function(func: Function) -> str:
    ssa = getattr(func, "ssa", False)

    if ssa:
        def value(v) -> str:
            return f"%{v.id}"

        params = ", ".join(
            f"{p.name}: {p.temp.type} @ {value(p.temp)}" for p in func.params
        )
    else:
        def value(v) -> str:
            return str(v)

        params = ", ".join(f"{p.name}: {p.slot.type} @ {value(p.slot)}"
                           for p in func.params)

    lines = [f"function {func.name}({params}) -> {func.ret_type} {{"]
    if not ssa and func.locals:
        lines.append("  locals:")
        for slot in func.locals:
            lines.append(f"    {value(slot)}: {slot.type}")
    for block in func.blocks:
        lines.append(f"  {block.label}:")
        if ssa:
            for phi in block.phis:
                lines.append(_render_phi(phi, value))
        for ins in block.instructions:
            lines.append(_render_instruction(ins, value))
        lines.append(_render_terminator(block.terminator, value))
    lines.append("}")
    return "\n".join(lines)


def render_module(module: Module) -> str:
    """Render a :class:`Module` to deterministic plain text."""
    parts = ["module"]
    parts.extend(_render_function(func) for func in module.functions)
    return "\n".join(parts) + "\n"

"""Dead-code elimination on pruned SSA form.

The entry point :func:`eliminate_dead_code` takes an SSA :class:`Module`
produced by :func:`~compiler_ir.ssa.to_ssa` and returns a brand new SSA
:class:`Module` with unreachable definitions removed; the input module is
never mutated and shares no mutable function, block, instruction or phi
container with the result.

Liveness is traced per function, definition-to-use, from fixed roots:

* every operand of a ``Return`` or ``Branch`` terminator;
* every ``Call`` instruction, regardless of whether its result is used --
  the call itself and its position in the instruction stream are observable
  behavior -- together with all of its argument definitions.

A ``Const``, ``BinOp`` or ``Phi`` that cannot reach one of those roots is
deleted.  The trace runs on the whole function at once, so chains feeding
only other dead definitions and closed phi cycles die together in one pass;
elimination is then repeated until no new dead definition appears.

The pass is purely subtractive.  No constants are folded, branches
rewritten, blocks deleted or control flow reordered.  Function order,
signatures, parameters, return types, block labels and order, terminators,
the relative order of surviving instructions and the predecessor order of
surviving phis are all preserved, and SSA numbers of surviving values are
left untouched (the output may therefore contain numbering holes).

Applying the pass to an already minimal module returns an independent,
structurally and textually equivalent copy, so a second
:func:`eliminate_dead_code` changes nothing.  A non-:class:`Module` object
raises :class:`TypeError`; a non-SSA :class:`Module` raises
:class:`ValueError`.
"""
from .ir_nodes import (
    BinOp,
    Block,
    Branch,
    Call,
    Const,
    Copy,
    Function,
    Jump,
    Module,
    Parameter,
    Phi,
    Return,
    Temp,
)


def eliminate_dead_code(module: Module) -> Module:
    """Return a new SSA :class:`Module` with dead definitions removed.

    The input module is left untouched; the result shares no mutable
    function, block, instruction or phi object with it.

    :raises TypeError: if ``module`` is not a :class:`Module` instance.
    :raises ValueError: if ``module`` is not in SSA form.
    """
    if not isinstance(module, Module):
        raise TypeError(
            "eliminate_dead_code expects a Module, got "
            f"{type(module).__name__}"
        )
    if not getattr(module, "ssa", False):
        raise ValueError("eliminate_dead_code expects an SSA Module")
    return Module(
        [_eliminate_in_function(func) for func in module.functions], ssa=True
    )


# --------------------------------------------------------------------------
# Operand helpers (mirror the ones used by the SSA conversion)
# --------------------------------------------------------------------------


def _operands(ins):
    if isinstance(ins, BinOp):
        return [ins.left, ins.right]
    if isinstance(ins, Call):
        return list(ins.args)
    # Const has no operands; a Copy cannot survive the non-SSA -> SSA
    # conversion (it folds into renaming) but is treated as pure anyway.
    if isinstance(ins, Copy):
        return [ins.src]
    return []


def _term_operands(term):
    if isinstance(term, Return) and term.value is not None:
        return [term.value]
    if isinstance(term, Branch):
        return [term.cond]
    return []


# --------------------------------------------------------------------------
# Per-function elimination
# --------------------------------------------------------------------------


def _live_definitions(func: Function) -> set:
    """Return the ids of values live from the terminator/call roots.

    Roots are every value read by a ``Return`` or ``Branch`` and *every*
    ``Call`` instruction (plus, transitively, its arguments): a call whose
    result is unused is still observable.  From each root the use-def graph
    -- instruction operands and phi incoming values -- is walked to a
    fixpoint, so a value only reachable from dead code or a closed phi
    cycle is absent from the result.
    """
    phi_by_dest: dict = {}
    operands_by_dest: dict = {}
    worklist: list = []

    for block in func.blocks:
        for ins in block.instructions:
            operands_by_dest[id(ins.dest)] = _operands(ins)
            if isinstance(ins, Call):
                # The call itself is a root even if its result is unused:
                # reaching its dest below also pulls in its arguments.
                worklist.append(ins.dest)
        worklist.extend(_term_operands(block.terminator))
        for phi in block.phis:
            phi_by_dest[id(phi.dest)] = phi

    live: set = set()
    while worklist:
        value = worklist.pop()
        if value is None or id(value) in live:
            continue
        live.add(id(value))
        phi = phi_by_dest.get(id(value))
        if phi is not None:
            worklist.extend(phi.entries.values())
        else:
            worklist.extend(operands_by_dest.get(id(value), ()))
    return live


def _eliminate_in_function(func: Function) -> Function:
    live = _live_definitions(func)

    new_blocks = [Block(block.id) for block in func.blocks]
    block_map = dict(zip(func.blocks, new_blocks))

    # Pre-create one fresh Temp for every surviving definition before
    # cloning anything: a phi in an earlier block (e.g. a loop header's
    # backedge entry) can reference an instruction defined in a later
    # block, and every retained use must resolve to the very same output
    # object.  Original ids are kept, so numbering holes from removed
    # definitions remain.
    value_map: dict = {
        id(param.temp): Temp(param.temp.id, param.temp.type)
        for param in func.params
    }
    for block in func.blocks:
        for phi in block.phis:
            if id(phi.dest) in live:
                value_map[id(phi.dest)] = Temp(phi.dest.id, phi.dest.type)
        for ins in block.instructions:
            if isinstance(ins, Call) or id(ins.dest) in live:
                value_map[id(ins.dest)] = Temp(
                    ins.dest.id, ins.dest.type
                )

    def map_value(value):
        if value is None:
            return None
        mapped = value_map.get(id(value))
        if mapped is None:
            # Defensive: a referenced value with no surviving definition.
            # Never occurs for SSA IR produced by to_ssa, where every
            # operand of a live construct is itself live.
            mapped = Temp(value.id, value.type)
            value_map[id(value)] = mapped
        return mapped

    for block, new_block in zip(func.blocks, new_blocks):
        for phi in block.phis:
            if id(phi.dest) not in live:
                continue
            entries = {
                block_map[pred]: map_value(value)
                for pred, value in sorted(
                    phi.entries.items(), key=lambda item: item[0].id
                )
            }
            new_block.phis.append(Phi(map_value(phi.dest), entries))

        for ins in block.instructions:
            if not isinstance(ins, Call) and id(ins.dest) not in live:
                continue
            dest = map_value(ins.dest)
            if isinstance(ins, Const):
                clone = Const(dest, ins.value)
            elif isinstance(ins, Copy):
                clone = Copy(dest, map_value(ins.src))
            elif isinstance(ins, BinOp):
                clone = BinOp(
                    dest, ins.operator, map_value(ins.left),
                    map_value(ins.right), ins.kind, ins.type,
                )
            else:
                clone = Call(
                    dest, ins.name,
                    [map_value(arg) for arg in ins.args], ins.type,
                )
            new_block.instructions.append(clone)

        term = block.terminator
        if isinstance(term, Return):
            new_block.terminator = Return(map_value(term.value))
        elif isinstance(term, Jump):
            new_block.terminator = Jump(block_map[term.target])
        elif isinstance(term, Branch):
            new_block.terminator = Branch(
                map_value(term.cond),
                block_map[term.true_target],
                block_map[term.false_target],
            )

    new_params = [
        Parameter(
            param.name,
            param.slot,
            map_value(param.temp),
        )
        for param in func.params
    ]

    return Function(
        func.name,
        new_params,
        func.ret_type,
        list(func.locals),
        new_blocks,
        block_map[func.entry],
        ssa=True,
    )

